import { randomBytes } from 'node:crypto';
import { sha256Hex } from './hmac';

/** URL-safe random token, 32 bytes by default (256 bits). */
export function randomToken(bytes = 32): string {
  return randomBytes(bytes).toString('base64url');
}

/** Only hashes of bearer tokens are stored, so a database leak does not expose usable tokens. */
export function hashToken(token: string): string {
  return sha256Hex(token);
}

/** Shopper session ids are generated by the widget: 22–64 URL-safe characters (≥128 bits). */
const SESSION_ID = /^[A-Za-z0-9_-]{22,64}$/;

export function isValidSessionId(value: unknown): value is string {
  return typeof value === 'string' && SESSION_ID.test(value);
}
